def direct_bounds(tx_list: list[dict]) -> tuple[dict[int, float], dict[int, float]]:
    """Bounds that need no algebra at all, from one fact in the payoff table.

    A fair charge is paid by EVERY reviewer - accepting pays a, refusing pays
    a plus the lawyer - while an inflated charge only pays the reviewers who
    accepted it. So for each (item, issuer):

        paid by all reviewers  ->  the charge was fair    ->  t >= charge
        paid by only some      ->  the charge was inflated ->  t <  charge

    The matchup-equation method leaves t_hi unbounded whenever the top interval
    stays feasible, which was every item in games 1-6. This recovers the upper
    side, and an upper bound is what makes over-estimation detectable at all.

    A charge nobody paid leaves no trace of its size, so it is skipped.
    """
    seen: dict[tuple[int, str], dict[str, float]] = collections.defaultdict(dict)
    for x in tx_list:
        seen[(x["line_item_index"], x["issuer"])][x["reviewer"]] = x["amount"]

    lo: dict[int, float] = {}
    hi: dict[int, float] = {}
    for (item, _issuer), revs in seen.items():
        paid = [a for a in revs.values() if a > 0]
