             .split('SYSTEM = """', 1)[1].split('"""', 1)[0])

K, UNCOVERED, BQ = 0.5, 0.6, 1 / 3

def tri_q(lo, mode, hi, q):
    lo, mode, hi = sorted((lo, mode, hi))
    if hi == lo: return lo
    f = (mode - lo) / (hi - lo)
    return lo + math.sqrt(q*(hi-lo)*(mode-lo)) if q <= f else hi - math.sqrt((1-q)*(hi-lo)*(hi-mode))

def num(x):
    try: v = float(x)
    except (TypeError, ValueError): return 0.0
    return v if math.isfinite(v) and v > 0 else 0.0

def price(est):
    cov = bool(est.get("covered")) and bool(est.get("related", True))
    lo, mid, hi = sorted(num(est.get(k)) for k in ("t_low", "t_mid", "t_high"))
    if not cov or mid <= 0:
        return round(UNCOVERED * (num(est.get("t_if_covered")) or mid), 2), 0.0
    spread = (hi - lo) / mid
    return round(max(lo, mid*(1 - K*spread)), 2), round(tri_q(lo, mid, hi, BQ), 2)

def user_msg(case):
    rows = "\n".join(f"  {i['index']} | {i['description']} | {i['quantity']:g} {i['unit']}"
