            f"<invoice {meta}>\n{case.invoice_text}\n</invoice>\n"
            + (f"\n<parsed_line_items>\n{rows}\n</parsed_line_items>\n" if case.items else ""))

async def estimate(system, case):
    c = await get_llm().complete([{"role": "user", "content": user_msg(case)}],
                                 system=system, max_tokens=16000)
    payload = extract_json(c.content) or {}
    return {int(i["index"]): i for i in payload.get("items", []) if "index" in i}

async def main():
    results = {}
    for g in GAMES:
