def tq(lo,mo,hi,q):
    lo,mo,hi=sorted((lo,mo,hi))
    if hi==lo: return lo
    f=(mo-lo)/(hi-lo)
    return lo+math.sqrt(q*(hi-lo)*(mo-lo)) if q<=f else hi-math.sqrt((1-q)*(hi-lo)*(hi-mo))
def num(x):
    try: v=float(x)
    except (TypeError,ValueError): return 0.0
    return v if math.isfinite(v) and v>0 else 0.0

def shade(lo,mid,hi,K):  # current a rule
    return max(lo, mid*(1-K*((hi-lo)/mid if mid else 0)))

